Translate the following GNU C++11 code to Java 8 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original GNU C++11 code you have to translate:
<original_code>
#include <bits/stdc++.h>
using namespace std;
#define mp make_pair

long long p, k;
const int MOD = 1e9 + 7;
long long w[1000100];

long long pow_mod(long long a, long long b)
{
    long long ret = 1;
    while(b)
    {
        if(b&1) ret = ret*a%MOD;
        b >>= 1;
        a = a*a %MOD;
    }
    return ret;
}

int main()
{
    cin >> p >> k;
    if(k == 1)
    {
        cout << pow_mod(p, p) << endl;
        return 0;
    }
    for(long long i=1;i<p;i++)
    {
        w[i] = k*i%p;
    }

    int cnt = 0;
    bool vis[1000100];
    memset(vis, false, sizeof(vis));

//    for(int i=1;i<p;i++)
//    {
//        cout << i << " " << w[i] << endl;
//    }

    for(int i=1;i<p;i++)
    {
        if(vis[i]) continue;
        int t = i;
        while(!vis[t])
        {
            vis[t] = true;
            t = w[t];
        }
        cnt ++;
    }
    //cout << "cnt:" << cnt << endl;
    cout << pow_mod(p, cnt) << endl;
    return 0;
}

</original_code>
